css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .38); position: relative; display: grid; grid-template-columns: repeat(6, 1fr); grid-template-rows: repeat(3, 1fr); gap: 6%; perspective: 320px; }
.loader span { border-radius: 50%; background: var(--accent-2); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 30%, transparent); transform-style: preserve-3d; animation: flipdot-turn calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
.loader span:nth-of-type(6n + 2) { animation-delay: calc(var(--loader-speed) * .16); }
.loader span:nth-of-type(6n + 3) { animation-delay: calc(var(--loader-speed) * .32); }
.loader span:nth-of-type(6n + 4) { animation-delay: calc(var(--loader-speed) * .48); }
.loader span:nth-of-type(6n + 5) { animation-delay: calc(var(--loader-speed) * .64); }
.loader span:nth-of-type(6n) { animation-delay: calc(var(--loader-speed) * .8); }
@keyframes flipdot-turn { 0%, 14% { transform: rotateX(0deg); background: var(--accent-2); } 30%, 62% { transform: rotateX(180deg); background: var(--accent); } 78%, 100% { transform: rotateX(360deg); background: var(--accent-2); } }
